var partsupp_facts = relationOfFacts(lpFacts['partsupp/2'] || []);
var q16_size_facts = relationOfFacts(lpFacts['q16_size/1'] || []);

var part = part_facts;

var partsupp = partsupp_facts;

var q16_size = q16_size_facts;

var part_by_5_6 = index(part, [4, 5]);
var instances_q16_part = [].concat(
  // q16_part(P,Brand,Size) :- part(P,_,_,Brand,medium,polished,_,Size,_,_), Brand \= brand45, q16_size(Size).
  (function() {
    return _.flatten(map(function(e1) {
      var P = e1.t[0];
      var Brand = e1.t[3];
      var Size = e1.t[7];
      if (Brand !== 'brand45') {
        return _.flatten(map(function(e2) {
          return [['q16_part', [P, Brand, Size], and([e1.v, e2.v])]];
        }, probe(q16_size, [Size])));
      } else {
        return [];
      }
    }, (part_by_5_6[keyOf(['medium', 'polished'])] || [])));
  })()
);
var q16_part = relation({}, instances_q16_part);

var q16_part_by_1 = index(q16_part, [0]);
var instances_q16_group = [].concat(
  // q16_group(Brand,Size) :- partsupp(P,_), q16_part(P,Brand,Size).
  (function() {
    return _.flatten(map(function(e1) {
      var P = e1.t[0];
      return _.flatten(map(function(e2) {
        var Brand = e2.t[1];
        var Size = e2.t[2];
        return [['q16_group', [Brand, Size], and([e1.v, e2.v])]];
      }, (q16_part_by_1[keyOf([P])] || [])));
    }, _.values(partsupp)));
  })()
);
var q16_group = relation({}, instances_q16_group);

var instances_q16 = [].concat(
  // q16 :- q16_group(_,_).
  (function() {
    return _.flatten(map(function(e1) {
      return [['q16', [], e1.v]];
    }, _.values(q16_group)));
  })()
);
var q16 = relation({}, instances_q16);

// component 0 bool
var model = function() {
  return [holds(q16, [])()];
};
Infer({method: 'enumerate'}, model);

